#!/usr/bin/env bash
# Fetches the Artlist-generated destination imagery and empty-state
# illustrations, converts them to web-sized files, and names them exactly as
# src/curatedMedia.js expects. Uses macOS's built-in `sips`, no installs.
#
# Run from the repo root:  bash scripts/fetch-curated-media.sh
set -euo pipefail

if ! command -v sips >/dev/null 2>&1; then
  echo "This script needs macOS's sips tool." >&2
  exit 1
fi

DEST=public/destinations
ILLO=public/illustrations
TMP=$(mktemp -d)
trap 'rm -rf "$TMP"' EXIT
mkdir -p "$DEST" "$ILLO"

