count=0
while IFS='|' read -r name kind url; do
  [ -z "$name" ] && continue
  raw="$TMP/$name.png"
  curl -fsSL -o "$raw" "$url"
  case "$kind" in
    hero) sips -s format jpeg -s formatOptions 80 -Z 1920 "$raw" --out "$DEST/$name.jpg" >/dev/null ;;
    card) sips -s format jpeg -s formatOptions 80 -Z 1600 "$raw" --out "$DEST/$name.jpg" >/dev/null ;;
    illo) sips -Z 640 "$raw" --out "$ILLO/$name.png" >/dev/null ;;
  esac
  count=$((count + 1))
  echo "saved $name"
done <<< "$IMAGES"

echo "Done: $count images."
du -sh "$DEST" "$ILLO"
